const TRAP={
1:"Do not use <i>and</i> when the two changes go in opposite directions. Use <b>but</b>. And always finish with <b>a / an + noun</b> (a drop, a rise), not a verb.",
2:"After + <b>-ing</b> means the <b>same subject</b> does both actions. <s>After rose to 4,000…</s> → <b>After rising</b> to 4,000…  Add the comma.",
3:"The two changes must be <b>opposite</b>. <s>Despite rising, the figure increased.</s> And never <s>Despite of</s>.",
4:"Put a <b>comma</b> before <i>after which</i> and follow it with <b>it / they</b> + verb.",
5:"Use <b>, reaching</b> (one subject, one finite verb). <s>…rose, reached 200.</s> and <s>…which reaching</s> are both wrong.",
6:"The word right after the comma must be the thing that <b>started</b> at that figure. <s>Starting at 5%, it rose…</s> (what is “it”?)",
7:"Structure 7 puts the subject first: <b>X started at 5%, a figure that then rose</b>. Do not forget <i>a figure that</i>.",
8:"<b>While</b> = contrast here. The two verbs must be <b>opposite</b>. Use <b>that for / those for</b> instead of repeating the noun.",
9:"<b>One subject only.</b> <s>…rose but then it fell</s> is a different structure. After and / but use a verb straight away.",
10:"<b>The former</b> = the first item you mention, <b>the latter</b> = the second. The item that changed <b>more</b> goes after <i>with</i>."
};
/* ---- structure patterns ---- */
const P = (re,msg,fl)=>({re:new RegExp(re,fl||"i"),msg});
const PAT = {
 s1:P("\\b(and|but) this was followed by (an?|the) ","Use: …, and / but this was followed by a(n) + noun."),
 s1but:P("\\bbut this was followed by (an?|the) ","Use: …, but this was followed by a(n) + noun (the two changes go in opposite directions)."),
 s1and:P("\\band this was followed by (an?|the) ","Use: …, and this was followed by a(n) + noun (the two changes go in the same direction)."),
 s2a:P("^after (\\w+ing\\b|an? |the )","Begin with After + -ing or After + a(n) adjective + noun."),
 s2aing:P("^after \\w+ing\\b","Begin with After + -ing (for example After rising …)."),
 s2anoun:P("^after (an?|the) ","Begin with After + a(n) adjective + noun (for example After a steady fall …)."),
 s2rising:P("^after rising\\b","Use After rising …"),
 s2bing:P("\\bbefore \\w+ing\\b","Use …, before + -ing (for example …, before dropping to …)."),
 s2aing_any:P("\\bafter \\w+ing\\b","Use After + -ing (for example After rising …)."),
 s3:P("^despite (\\w+ing\\b|an? |the )","Begin with Despite + -ing or Despite + a(n) noun."),
 s3ing:P("^despite \\w+ing\\b","Begin with Despite + -ing (for example Despite rising …)."),
 s3noun:P("^despite (an?|the) ","Begin with Despite + a(n) adjective + noun (for example Despite a rise …)."),
 s4:P(",\\s*after which\\b","Use …, after which … (with a comma)."),
 s5:P(",\\s*reaching\\b","Use …, reaching + figure (with a comma)."),
 s6:P("^starting at ","Begin with Starting at + figure, then the subject."),
 s7:P("\\bstarted at\\b[\\s\\S]*\\ba figure that then\\b","Use: X started at + figure, a figure that then + verb."),
 s7loose:P("\\bstarted at\\b[\\s\\S]*\\ba figure that (then )?\\w+","Use: X started at + figure, a figure that (then) + verb."),
 s8:P("^while\\b[^,]+,","Begin with While + clause, then a comma and the contrasting clause."),
 s8that:P(",\\s*(that|those) (of|for)\\b","Use that of / that for (or those of / those for) to avoid repeating the noun."),
 s9:P("\\b(and|but)( then)? [a-z]+","Join the two changes with and / but (then) + verb."),
 s9but:P("\\bbut( then)? [a-z]+","Use but (then) + verb for a contrast."),
 s10:P(",\\s*with\\b[\\s\\S]*\\bseeing\\b","Use: …, with the former / the figure for X seeing a bigger + noun."),
 former:P("\\bthe former\\b","Use the former (the first one you mention)."),
 figfor:P("with (the (figure|rate|proportion|percentage|number) for|that (for|of)) ","Use: with the figure for X seeing …"),
 nowhich:{re:/\bwhich\b/i,not:true,msg:"Remove the word which: use an -ing phrase or a noun phrase."},
 "!s1":{re:/this was followed by/i,not:true,msg:"Do not use 'this was followed by' here: join with and / but + verb."}
};
